// ee/EEWorldConstants.h: the dbworld constants by their ids (docs/DATA_FORMATS.md 8.3). The enum EEWorldConstant is
// Rust's (ee_data world_constants.rs, generated by tools/eedata/cppgen.py from tools/eedata/specs.json's
// overlay.WORLD_ROWS), emitted back as a plain C++ enum. The EEWorldTable accessors take an EEWorldConstant, so a raw
// row number does not compile.
#ifndef EE_EEWORLDCONSTANTS_H
#define EE_EEWORLDCONSTANTS_H

#include "rust/data/world_constants.h"

// the research times of the unit improvements: one row per improvement kind, from improvement_time_area_effect
inline EEWorldConstant EEWorldImprovementTime(long inKind)
{
    return static_cast<EEWorldConstant>(kWorldImprovementTimeAreaEffect + inKind);
}

#endif
